{
    // The header's own note is to use this singleton, so it is one object for the process.
    static INFocusStatusCenter *shared;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        shared = [[INFocusStatusCenter alloc] init];
    });
    return shared;
}

